SELECT /* LGSYSC00140.retrieveProgramList */ a.system_code , a.module_code , a.program_id , a.program_name , a.program_type_code , a.business_effect_code , a.difficulty_code , TO_CHAR(a.transfer_date,'YYYY-MM-DD') AS transfer_date , a.use_flag , DECODE(NVL(b.use_count,0),0,'N','Y') AS is_menu , etc_attach_file_id , a.link_url_addr FROM LGCOM_PROGRAM_M a , ( SELECT program_id , COUNT(menu_id) AS use_count FROM LGCOM_MENU_M GROUP BY program_id ) b WHERE a.program_id = b.program_id(+)
AND a.system_code = #{systemCode}
AND a.module_code = #{moduleCode}
AND a.program_name LIKE #{programName} || '%'
AND a.use_flag = #{useFlag}
ORDER BY a.system_code, a.module_code, a.program_id

mapper.update:
UPDATE LGCOM_PROGRAM_M   /* LGSYSC00140.updateProgramList */ 
   SET program_name         = #{programName}
     , system_code          = #{systemCode}
     , module_code          = #{moduleCode}
     , program_type_code    = #{programTypeCode}
     , business_effect_code = #{businessEffectCode}
     , difficulty_code      = #{difficultyCode}
     , transfer_date        = TO_DATE(#{transferDate},'YYYY-MM-DD')
     , ETC_ATTACH_FILE_ID   = #{etcAttachFileId}
     , link_url_addr        = #{linkUrlAddr}
     , use_flag             = #{useFlag}
     , last_updated_by      = #{sessionUserId}
     , last_update_date     = SYSDATE
 WHERE program_id            = #{programId}

UPDATE LGCOM_PROGRAM_M /* LGSYSC00140.deleteProgramList */ 
   SET use_flag         = 'N'
     , last_updated_by  = #{sessionUserId}
     , last_update_date = SYSDATE
 WHERE program_id       = #{programId}

mapper.select:
select /* LGSYSC00140.createDirectCSVDownloadData */ system_code , module_code , program_id , program_name , program_type_code , business_effect_code , difficulty_code , transfer_date , use_flag , is_menu , etc_attach_file_id , link_url_addr FROM ( SELECT '1' gubun , 'Sytem Code' AS SYSTEM_CODE , 'Module Code' AS MODULE_CODE , 'Program Id' AS PROGRAM_ID , 'Program Name' AS PROGRAM_NAME , 'Program Type Code' AS PROGRAM_TYPE_CODE , 'Business Effect Code' AS BUSINESS_EFFECT_CODE , 'Difficulty Code' AS DIFFICULTY_CODE , 'Transfer Date' AS TRANSFER_DATE , 'Use Flag' AS USE_FLAG , 'Menu Flag' AS IS_MENU , 'Attachment File ID' AS ETC_ATTACH_FILE_ID , 'Link Addr' AS link_url_addr FROM DUAL UNION ALL SELECT '2' gubun , a.system_code , a.module_code , a.program_id , a.program_name , a.program_type_code , a.business_effect_code , a.difficulty_code , TO_CHAR(a.transfer_date,'YYYY-MM-DD') AS transfer_date , a.use_flag , DECODE(NVL(b.use_count,0),0,'N','Y') AS is_menu , to_char(etc_attach_file_id) AS etc_attach_file_id , a.link_url_addr FROM LGCOM_PROGRAM_M a , ( SELECT program_id , COUNT(menu_id) AS use_count FROM LGCOM_MENU_M GROUP BY program_id ) b WHERE a.program_id = b.program_id(+)
AND a.system_code = #{systemCode}
AND a.module_code = #{moduleCode}
AND a.program_name LIKE #{programName} || '%'
AND a.use_flag = #{useFlag}
) ORDER BY gubun, system_code, module_code, program_id

