INSERT INTO /* LGSYSC00140.createExcelDownloadData */ XXLGE_EXPORT_INFO (SESSION_ID, CREATED_BY, CREATION_DATE, SEQ_NO, CHARACTER_SET_NAME , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5 , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 , ATTRIBUTE11 , ATTRIBUTE12 ) SELECT #{sessionId} , #{USER_SESSION.applicationUserId} , SYSDATE , 1 AS ORDER_BY , 'KO16KSC5601' , 'Sytem Code' AS SYSTEM_CODE , 'Module Code' AS MODULE_CODE , 'Program Id' AS PROGRAM_ID , 'Program Name' AS PROGRAM_NAME , 'Program Type Code' AS PROGRAM_TYPE_CODE , 'Business Effect Code' AS BUSINESS_EFFECT_CODE , 'Difficulty Code' AS DIFFICULTY_CODE , 'Transfer Date' AS TRANSFER_DATE , 'Use Flag' AS USE_FLAG , 'Menu Flag' AS IS_MENU , 'Attachment File ID' AS ETC_ATTACH_FILE_ID , 'BiMatrix Id' AS link_url_addr FROM DUAL
UNION ALL
SELECT #{sessionId} , #{USER_SESSION.applicationUserId} , SYSDATE , 2 AS ORDER_BY , 'KO16KSC5601' , A.SYSTEM_CODE , A.MODULE_CODE , A.PROGRAM_ID , A.PROGRAM_NAME , A.PROGRAM_TYPE_CODE , A.BUSINESS_EFFECT_CODE , A.DIFFICULTY_CODE , TO_CHAR(A.TRANSFER_DATE,'YYYY-MM-DD') AS TRANSFER_DATE , A.USE_FLAG , DECODE(NVL(B.USE_COUNT,0),0,'N','Y') AS IS_MENU , TO_CHAR(ETC_ATTACH_FILE_ID) AS ETC_ATTACH_FILE_ID , a.link_url_addr FROM LGCOM_PROGRAM_M A , ( SELECT PROGRAM_ID , COUNT(MENU_ID) AS USE_COUNT FROM LGCOM_MENU_M GROUP BY PROGRAM_ID ) B WHERE A.PROGRAM_ID = B.PROGRAM_ID(+)
AND A.SYSTEM_CODe = #{systemCode}
AND A.MODULE_CODE = #{moduleCode}
AND A.PROGRAM_NAME LIKE #{programName} || '%'
AND A.USE_FLAG = #{useFlag}
ORDER BY ORDER_BY, SYSTEM_CODE, MODULE_CODE, PROGRAM_ID

